    adcs_vec3_t u, v, c;
    double dot;
    double sep;
    double cond;

    if ((first == NULL) || (second == NULL) || (separation_rad == NULL) || (conditioning == NULL)) {
        if (separation_rad != NULL) {
            *separation_rad = 0.0;
        }
        if (conditioning != NULL) {
            *conditioning = 0.0;
        }
        return ADCS_E_NULL;
    }

    *separation_rad = 0.0;
    *conditioning = 0.0;

    if ((!adcs_is_finite_vec3(first)) || (!adcs_is_finite_vec3(second))) {
        return ADCS_E_DEGENERATE;
    }

    if (adcs_vec3_normalize(first, ADCS_EPS_NORM, &u) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }
    if (adcs_vec3_normalize(second, ADCS_EPS_NORM, &v) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    dot = adcs_vec3_dot(&u, &v);
    sep = acos(ADCS_CLAMP(dot, -1.0, 1.0));

    c = adcs_vec3_cross(&u, &v);
    cond = adcs_vec3_norm(&c);

    *separation_rad = sep;
    *conditioning = cond;

    return ADCS_OK;
}

